#include "evengine/studio.hpp"
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
using namespace evengine;
int main(int argc,char** argv){try{StudioGame g(argv[1]);int checks=0;auto check=[&](bool ok,const char* n){if(!ok)throw std::runtime_error(n);checks++;std::cout<<"OK "<<n<<'\n';};Input in;auto press=[&](Action a){in={};in.set(a,true);g.update(in,Tick);in.consume();in.set(a,false);};auto &s=g.project.scenes.at("meadow");auto object=[&](const std::string& id)->const Object&{for(auto &o:s.objects)if(o.id==id)return o;throw std::runtime_error("Missing object");};
 check(g.items.size()==3&&g.project.sprites.size()==80,"demo includes inventory and expanded assets");check(g.inventory.empty(),"inventory begins empty");g.feet={128,208};press(Action::Interact);check(g.dialogueObject=="meadow:keeper"&&g.dialoguePage==0,"NPC opens first page");in={};in.set(Action::Right,true);auto feet=g.feet;g.update(in,Tick);check(g.feet.x==feet.x,"dialogue pauses movement");press(Action::Interact);check(g.dialoguePage==1,"E advances dialogue page");press(Action::Interact);check(g.dialogueObject.empty(),"last page closes dialogue");
 g.feet={128,208};press(Action::Interact);press(Action::Attack);check(g.dialogueObject.empty()&&g.attackClock<0,"Space dismisses without attacking");g.feet={232,156};press(Action::Interact);check(!g.activated.count("meadow:key-door")&&g.toast.find("Bronze key")!=std::string::npos,"locked door explains missing key");
 auto closed=g.collisionScene("meadow",g.removed,g.activated);check(blocked(g.project,closed,body({248,156})),"closed door blocks its passage");g.feet={176,217};press(Action::Interact);check(g.inventory.at("bronze-key")==1&&g.activated.count("meadow:key-chest"),"chest awards one key");press(Action::Interact);check(g.inventory.at("bronze-key")==1,"opened chest cannot duplicate reward");check(g.visibleSprite(object("key-chest"))=="eve-chest-open","opened chest uses alternate art");
 g.feet={232,156};press(Action::Interact);check(g.activated.count("meadow:key-door")&&!g.inventory.count("bronze-key"),"door opens and consumes one key");auto open=g.collisionScene("meadow",g.removed,g.activated);check(!blocked(g.project,open,body({248,156})),"opened door clears collision");check(g.visibleSprite(object("key-door"))=="eve-door-open","opened door uses alternate art");
 in={};in.set(Action::Right,true);g.feet={232,156};for(int i=0;i<30;i++){g.update(in,Tick);in.consume();}check(g.feet.x>255,"player walks through opened passage");
 g.feet={374,204};press(Action::Interact);check(!g.activated.count("meadow:garden-gate"),"switch-only gate resists manual use");g.feet={348,248};press(Action::Interact);check(g.activated.count("meadow:garden-lever")&&g.activated.count("meadow:garden-gate"),"switch opens linked gate");auto events=g.soundEvents.size();press(Action::Interact);check(g.soundEvents.size()==events,"latched switch does not repeat cue");
 g.feet={112,254};in={};g.update(in,Tick);check(g.inventory.at("gold-coin")==3,"pickup can award item quantities");g.update(in,Tick);check(g.inventory.at("gold-coin")==3,"pickup is one-time");press(Action::Menu);check(g.inventoryOpen,"Q/I action opens bag");in={};in.set(Action::Right,true);feet=g.feet;g.update(in,Tick);check(g.feet.x==feet.x,"bag pauses world movement");press(Action::Quit);check(!g.inventoryOpen&&!g.quit,"Escape closes bag before quitting");
 std::string error,path=(std::filesystem::path(argv[2])/"interactions-save.dat").string();g.feet={248,156};check(g.save(path,error),"interaction save written atomically");StudioGame restored(argv[1]);check(restored.load(path,error),"save accepts a position inside an opened door");check(restored.activated==g.activated&&restored.inventory==g.inventory&&restored.removed==g.removed,"save restores inventory and object states");
 auto oldFeet=restored.feet;auto corrupt=(std::filesystem::path(argv[2])/"corrupt-interactions.dat").string();std::ifstream f(path);std::string text((std::istreambuf_iterator<char>(f)),{});auto at=text.find("\"gold-coin\" 3");check(at!=std::string::npos,"inventory fixture present");text.replace(at,13,"\"unknown\" 3");std::ofstream(corrupt)<<text;check(!restored.load(corrupt,error)&&restored.feet.x==oldFeet.x&&restored.inventory==g.inventory,"corrupt inventory rejects without partial mutation");
 auto legacy=(std::filesystem::path(argv[2])/"legacy-studio.dat").string();check(saveState(legacy,{g.project.id,"meadow",{88,232},7,{}},error)&&restored.load(legacy,error)&&restored.score==7,"legacy progress saves still load");
 restored.inventory["gold-coin"]=999;check(!restored.giveItem("gold-coin",1)&&restored.inventory.at("gold-coin")==999,"inventory cap prevents silent item loss");
 g.scene="grove";g.feet={200,202};press(Action::Interact);check(g.inventory.at("trail-bread")==2,"reward chest works across maps");g.inventoryOpen=true;SoftwareRenderer r;r.render(g.draw(),g.atlas);r.writePPM((std::filesystem::path(argv[2])/"v06-inventory.ppm").string());g.inventoryOpen=false;g.scene="meadow";g.feet={220,190};r.render(g.draw(),g.atlas);r.writePPM((std::filesystem::path(argv[2])/"v06-playtest.ppm").string());g.dialogueObject="meadow:keeper";g.dialoguePage=1;g.dialogueSpeaker="Grove keeper";r.render(g.draw(),g.atlas);r.writePPM((std::filesystem::path(argv[2])/"v06-dialogue.ppm").string());check(r.pixels.size()==Width*Height,"dialogue and inventory render through native Canvas");
 std::cout<<checks<<" interaction checks passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
